#!/usr/bin/env python3
"""Convert the PNGs in this directory into LVGL images in ../widgets/art.c.

Each PNG is drawn upright, the way you see it on the keyboard: 68 px wide and
up to 140 px tall, dark pixels = ink. The image is named art_<file stem>.

Usage: python3 gen_art.py   (needs Pillow)
"""

import re
from pathlib import Path

from PIL import Image

HERE = Path(__file__).resolve().parent
OUT = HERE.parent / "widgets" / "art.c"
WIDTH = 68

HEADER = """/*
 * Generated by art/gen_art.py from the PNGs in art/ - do not edit by hand.
 *
 * SPDX-License-Identifier: MIT
 */

#include <lvgl.h>

#ifndef LV_ATTRIBUTE_MEM_ALIGN
#define LV_ATTRIBUTE_MEM_ALIGN
#endif
"""

PALETTE = """#if CONFIG_SHARP_MIP_WIDGET_INVERTED
        0xff, 0xff, 0xff, 0xff, /*Color of index 0*/
        0x00, 0x00, 0x00, 0xff, /*Color of index 1*/
#else
        0x00, 0x00, 0x00, 0xff, /*Color of index 0*/
        0xff, 0xff, 0xff, 0xff, /*Color of index 1*/
#endif
"""


def pack(img: Image.Image) -> list[int]:
    """LV_IMG_CF_INDEXED_1BIT rows, MSB first; ink = index 0 (foreground)."""
    out = []
    for y in range(img.height):
        for x0 in range(0, img.width, 8):
            byte = 0
            for bit in range(8):
                x = x0 + bit
                paper = x < img.width and img.getpixel((x, y)) >= 128
                byte |= paper << (7 - bit)
            out.append(byte)
    return out


def hex_rows(data: list[int]) -> str:
    return "\n".join(
        "        " + " ".join(f"0x{b:02x}," for b in data[i : i + 15])
        for i in range(0, len(data), 15)
    )


def convert(path: Path) -> str:
    name = "art_" + re.sub(r"\W", "_", path.stem)
    upright = Image.open(path).convert("L")
    if upright.width != WIDTH or upright.height > 140:
        raise SystemExit(f"{path.name}: must be {WIDTH} px wide and at most 140 px tall")

    # The panel is mounted sideways: upright top = panel right edge.
    panel = upright.transpose(Image.ROTATE_270)
    normal = pack(panel)
    flipped = pack(panel.transpose(Image.ROTATE_180))

    return f"""
const LV_ATTRIBUTE_MEM_ALIGN LV_ATTRIBUTE_LARGE_CONST uint8_t {name}_map[] = {{
{PALETTE}
#ifdef CONFIG_SHARP_MIP_ROTATE_180
{hex_rows(flipped)}
#else
{hex_rows(normal)}
#endif
}};

const lv_img_dsc_t {name} = {{
    .header.cf = LV_IMG_CF_INDEXED_1BIT,
    .header.always_zero = 0,
    .header.reserved = 0,
    .header.w = {panel.width},
    .header.h = {panel.height},
    .data_size = {8 + len(normal)},
    .data = {name}_map,
}};
"""


def main() -> None:
    pngs = sorted(HERE.glob("*.png"))
    OUT.write_text(HEADER + "".join(convert(p) for p in pngs))
    print(f"wrote {OUT} ({', '.join(p.name for p in pngs)})")


if __name__ == "__main__":
    main()
